/**
 * Nigeria state boundaries, compiled into the bundle.
 *
 * Generated by scripts/build-boundaries.mjs. Do not edit by hand.
 *
 * Source: geoBoundaries gbOpen ADM1 for Nigeria, build 9469f09, from GRID3
 * Nigeria state boundaries. Licensed CC BY 4.0, so the attribution is carried
 * here and rendered on the map itself.
 *
 * This file exists so the map can draw the country without asking a tile server
 * to do it. A tile request would disclose the visitor's IP address and the
 * exact rectangle they are looking at, which is the one thing this site does
 * not do.
 */

import boundaries from "./nigeria-boundaries.json";

export const BOUNDARY_ATTRIBUTION = boundaries.attribution;
export const BOUNDARY_SOURCE_URL = boundaries.source;

/**
 * GeoJSON feature collection of state outlines, shaped for Leaflet.
 *
 * Only `name` is kept on each feature: nothing on the map is clickable, and
 * carrying the rest of the upstream property bag would just be payload.
 */
export const STATE_BOUNDARIES = {
  type: "FeatureCollection",
  features: boundaries.states.map((state) => ({
    type: "Feature",
    properties: { name: state.name },
    geometry: state.geometry,
  })),
};

export default STATE_BOUNDARIES;
